%[text] ## Read Table and analyze
clearvars
fname = matlab.desktop.editor.getActiveFilename;  % full filename (empty if none)
folder = fileparts(fname); 
xclFile = fullfile(folder, "quiz-multi-groups.csv")  %[output:4462b04d]
%%

T = readtable('quiz-multi-groups.csv');
T.Quiz = categorical(T.Quiz,unique(T.Quiz), ["Post" "Pre"],ordinal=true ); % convert to categorical
T.Quiz = reordercats(T.Quiz,["Pre" "Post"]); % Reorder categories, so Pre is plotted first
T.Treatment = categorical(T.Treatment);
%%
%[text] ### Group Summary
stats = groupsummary(T, ["Quiz","Treatment"], ["mean" "std"], "Score") %[output:4e72daf2]
%[output:2471f481]

%%
mmSetFigPublication %[output:53472b24]
%%
figure
bar(stats,["Treatment"],"mean_Score") %[output:325ff8ef]
legend(Location="northwest")

%%
figure; %[output:4901b362]
boxchart(T.Treatment, T.Score, ... % First Grouping by Treatment %[output:4901b362]
    GroupByColor = T.Quiz, ... % second grouping by quiz %[output:4901b362]
    Notch="on"); % turn notch on %[output:4901b362]
ylim([0 10]) %[output:4901b362]
legend(categories(T.Quiz),Location="southeast") %[output:4901b362]
%%
figure; %[output:1a7496e5]

% create boxplot
hbc = boxchart(T.Treatment, T.Score,GroupByColor = T.Quiz,Notch="off"); %[output:1a7496e5]
ylim([0 10]) %[output:1a7496e5]
ylabel('Score') %[output:1a7496e5]


% plot data points
hold on %[output:1a7496e5]
offset = 0.15; % offsets x-position of data points
sz = 15; % marker size
xjw = 0.15; % jitter width
mfa = 0.1; % marker face alpha

% plot prequiz data
swarmchart(single(hbc(1).XData)-offset,hbc(1).YData,sz,'filled', ... %[output:1a7496e5]
    XJitter='density',... %[output:1a7496e5]
    XJitterWidth=xjw, ... %[output:1a7496e5]
    MarkerFaceColor='k',... %[output:1a7496e5]
    MarkerFaceAlpha=mfa) %[output:1a7496e5]

% plot postquiz data
swarmchart(single(hbc(2).XData)+offset,hbc(2).YData,sz,'filled', ... %[output:1a7496e5]
    XJitterWidth=xjw, ... %[output:1a7496e5]
    MarkerFaceColor='k',... %[output:1a7496e5]
    MarkerFaceAlpha=mfa) %[output:1a7496e5]

% move scatter plots underneath box plots
ax = gca;
chH = ax.Children; 
ax.Children = flipud(chH); %[output:1a7496e5]

% add legend
legend(hbc, categories(T.Quiz),Location="southeast") % input boxchart handle to only add a legend for those plots %[output:1a7496e5]
%%
%[text] ### 
%[text] ## Create Table
clearvars
%%
T = add_scores(50, 5, 1.4, "Pre",  "Control");
T = [T; add_scores(50, 5, 1.3, "Pre",  "Experiment")];
T = [T; add_scores(50, 6, 1.4, "Post", "Control")];
T = [T; add_scores(50, 8, 1.3, "Post", "Experiment")];
T.Score(T.Score>10) = 10;
T = convertvars(T,["Quiz" "Treatment"],'categorical');
T.Quiz = reordercats(T.Quiz,["Pre" "Post"]);


figure; %[output:6747d1dc]
hbc = boxchart(T.Treatment, T.Score,GroupByColor = T.Quiz,Notch="off"); %[output:6747d1dc]
ylim([0 10]) %[output:6747d1dc]
legend(categories(T.Quiz),Location="southeast") %[output:6747d1dc]
%%
writetable(T,'quiz-multi-groups.csv')
%%
function t = add_scores(n, mu, sigma, quiz, treatment)

scores = sigma.*randn(n,1)+mu; % generate random numbers with mean mu and std sigma
scores = uint8(scores);

t = table(repmat(quiz,n,1), repmat(treatment,n,1), scores, VariableNames = ["Quiz" "Treatment" "Score"]);
end
%%
%[text] ### Pre-Experimental
mu = 5; % mean height of women as reported on google
sigma = 1.5; % standard deviation
scores = sigma.*randn(n,1)+mu; % generate random numbers with mean mu and std sigma
scores = uint8(scores);

t = table(repmat("Pre",n,1), repmat("Experiment",n,1), scores,VariableNames = ["Quiz" "Treatment" "Score"]);
T = [T;t];
%%
T = convertvars(T,["Quiz" "Treatment"],'categorical');
boxchart(T.Treatment, T.Score)

%%

boxchart(scores)
%%
histogram(scores) % plot histogram
xline(mu,'--r','mean')
title(sprintf("Average Female Height = %1.2f±%1.2f",mu,sigma))
xlabel("Height (in)")

